result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/dedup.py", "content": "#!/usr/bin/env python3
"""Duplicate-file finder.

Finds duplicate files under one or more directories using staged
comparison so expensive work happens only when necessary:

1. Group candidates by file size (cheap stat).
2. Within equal-size groups, group by sha256 of the first 4 KiB.
3. Only candidates that survive both stages get a full sha256.

Usage:
    python dedup.py DIR [DIR ...] [--stats] [--delete]

Prints groups of duplicate paths, one group per block (paths separated
by newlines, groups separated by a blank line).  With --stats, reports
how many full hashes were computed (on stderr).  With --delete, keeps
the first path of each group, removes the rest and prints the total
reclaimed bytes.
"""

from __future__ import annotations

import argparse
import hashlib
import os
import sys
from collections import defaultdict

CHUNK_SIZE = 4096  # bytes covered by the partial (first-stage) hash


def iter_files(roots):
    """Yield paths of all regular files under the given roots."""
    for root in roots:
        if os.path.isfile(root):
            yield root
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            dirnames.sort()
            for name in sorted(filenames):
                yield os.path.join(dirpath, name)


def sha256_path(path, limit=None):
    """Return hex sha256 of *path*, reading at most *limit* bytes."""
    h = hashlib.sha256()
    remaining = limit
    with open(path, "rb") as fh:
        while True:
            want = CHUNK_SIZE if remaining is None else min(CHUNK_SIZE, remaining)
            if want == 0:
                break
            data = fh.read(want)
            if not data:
                break
            h.update(data)
            if remaining is not None:
                remaining -= len(data)
    return h.hexdigest()


class DuplicateFinder:
    """Staged duplicate finder with instrumentation."""

    def __init__(self):
        self.full_hashes = 0

    def find(self, roots):
        """Return a list of duplicate groups.

        Each group is a sorted list of paths whose contents are
        identical.  Groups are ordered deterministically (by size,
        then first path).
        """
        # Stage 1: group by size.
        by_size = defaultdict(list)
        for path in iter_files(roots):
            try:
                size = os.path.getsize(path)
            except OSError:
                continue  # vanished while scanning
            by_size[size].append(path)

        groups = []
        for size in sorted(by_size):
            candidates = sorted(by_size[size])
            if len(candidates) < 2:
                continue

            # Stage 2: group by hash of the first 4 KiB.
            by_prefix = defaultdict(list)
            for path in candidates:
                try:
                    prefix_hash = sha256_path(path, limit=CHUNK_SIZE)
                except OSError:
                    continue
                by_prefix[prefix_hash].append(path)

            # Stage 3: full hash only where prefix hashing left doubt.
            for prefix_group in by_prefix.values():
                if len(prefix_group) < 2:
                    continue
                by_full = defaultdict(list)
                for path in prefix_group:
                    try:
                        self.full_hashes += 1
                        digest = sha256_path(path)
                    except OSError:
                        continue
                    by_full[digest].append(path)
                for full_group in by_full.values():
                    if len(full_group) >= 2:
                        groups.append(sorted(full_group))
        return groups


def main(argv=None):
    parser = argparse.ArgumentParser(description="Find duplicate files.")
    parser.add_argument("dirs", nargs="+", help="directories to scan")
    parser.add_argument(
        "--stats",
        action="store_true",
        help="report how many full hashes were computed",
    )
    parser.add_argument(
        "--delete",
        action="store_true",
        help="keep the first path of each group, remove the rest",
    )
    args = parser.parse_args(argv)

    finder = DuplicateFinder()
    groups = finder.find(args.dirs)

    reclaimed = 0
    for group in groups:
        for line in group:
            print(line)
        print()  # blank line between groups

        if args.delete:
            keeper, extras = group[0], group[1:]
            for extra in extras:
                try:
                    reclaimed += os.path.getsize(extra)
                    os.remove(extra)
                except OSError as exc:
                    print(f"warning: cannot remove {extra}: {exc}", file=sys.stderr)

    if args.delete:
        print(f"Reclaimed {reclaimed} bytes")
    if args.stats:
        print(f"Full hashes computed: {finder.full_hashes}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
